export function validateMALEREPRODUCTIVESeed(): void {
  const slugs = new Set(
    MALE_REPRODUCTIVE_STRUCTURES.map((structure) => structure.slug),
  );
  if (slugs.size !== MALE_REPRODUCTIVE_STRUCTURES.length) {
    throw new Error(
      'Male reproductive system seed contains duplicate structure slugs.',
    );
  }
  const meshNames = new Set(
    MALE_REPRODUCTIVE_STRUCTURES.map((structure) => structure.meshName),
  );
  if (meshNames.size !== MALE_REPRODUCTIVE_STRUCTURES.length) {
    throw new Error(
      'Male reproductive system seed contains duplicate mesh names.',
    );
  }
  if (MALE_REPRODUCTIVE_STRUCTURES.length !== 10) {
    throw new Error(
      'Male reproductive system seed must contain exactly 10 structures.',
    );
  }
  for (const structure of MALE_REPRODUCTIVE_STRUCTURES) {
    for (const relatedSlug of structure.relatedSlugs) {
      if (!slugs.has(relatedSlug)) {
        throw new Error(
          `Structure "${structure.slug}" references unknown related slug "${relatedSlug}".`,
        );
      }
    }
    if (structure.references.length === 0) {
      throw new Error(`Structure "${structure.slug}" has no references.`);
    }
    if (
      structure.meshName !== null &&
      !/^[a-z0-9_]+$/.test(structure.meshName)
    ) {
      throw new Error(
        `Structure "${structure.slug}" has an invalid mesh name "${structure.meshName}".`,
      );
    }
  }
}
